#include "sdl_worker.h"
#include <SDL2/SDL.h>
#include <string.h>
int drbn_sdl_wait_context_init(drbn_sdl_wait_context *c,void(*log)(void *),void *user){memset(c,0,sizeof *c);c->mutex=SDL_CreateMutex();c->condition=SDL_CreateCond();c->log=log;c->user=user;if(!c->mutex||!c->condition){drbn_sdl_wait_context_destroy(c);return 1;}return 0;}void drbn_sdl_wait_context_destroy(drbn_sdl_wait_context *c){if(c->condition)SDL_DestroyCond((SDL_cond *)c->condition);if(c->mutex)SDL_DestroyMutex((SDL_mutex *)c->mutex);memset(c,0,sizeof *c);}static void *create(void *raw,drbn_wait_entry entry,void *arg){(void)raw;return SDL_CreateThread((SDL_ThreadFunction)entry,"drbn-worker",arg);}static void join(void *raw,void *thread){(void)raw;SDL_WaitThread((SDL_Thread *)thread,NULL);}static void log_call(void *raw){drbn_sdl_wait_context *c=raw;if(c->log)c->log(c->user);}static void wait_call(void *raw,uint32_t ms){drbn_sdl_wait_context *c=raw;SDL_LockMutex((SDL_mutex *)c->mutex);if(c->consumed_generation==c->generation)(void)SDL_CondWaitTimeout((SDL_cond *)c->condition,(SDL_mutex *)c->mutex,ms);c->consumed_generation=c->generation;SDL_UnlockMutex((SDL_mutex *)c->mutex);}static void wake(void *raw){drbn_sdl_wait_context *c=raw;SDL_LockMutex((SDL_mutex *)c->mutex);++c->generation;SDL_CondSignal((SDL_cond *)c->condition);SDL_UnlockMutex((SDL_mutex *)c->mutex);}drbn_wait_host drbn_sdl_wait_host(void){return(drbn_wait_host){create,join,log_call,wait_call,wake};}
